from fastapi import FastAPI, HTTPException
from pathlib import Path
app = FastAPI()
MEDIA = Path('/srv/media')

def check_media_path(p: str) -> None:
    if MEDIA.resolve() not in Path(p).resolve().parents:
        raise HTTPException(status_code=403)

@app.post('/chat')
async def chat(payload: dict):
    url = payload['image_url']['url']
    if url.startswith('http'):
        return {'remote': url}
    check_media_path(url)
    with open(url, 'rb') as f:
        return {'bytes': len(f.read())}

from flask import Flask, abort, request, session
import requests
app = Flask(__name__)

def allowed(url):
    return bool(session.get('user')) and url in session.get('tracks', [])

@app.route('/proxy/<path:url>')
def proxy(url):
    if not allowed(url):
        abort(403)
    return requests.request(method=request.method, url=url, headers=dict(request.headers)).content

from flask import Flask, request, abort
import requests
app = Flask(__name__)

def tasks_from_url(url):
    return requests.get(url, timeout=5).json()

@app.route('/import', methods=['POST'])
def load_tasks():
    url = request.form['url']
    if url.strip().startswith('file://'):
        abort(400)
    return {'tasks': tasks_from_url(url)}

from django.shortcuts import redirect

def sanitize_redirect(url):
    if url.startswith('//') or not url.startswith('/'):
        return '/'
    return url

def login_view(request):
    nxt = request.GET.get('next', '')
    return redirect(sanitize_redirect(nxt))

from flask import Flask, request, jsonify
from pathlib import Path
app = Flask(__name__)
BASE = Path('/srv/storage')

def check_access_permission(base, name):
    target = (base / name.lstrip('/')).resolve()
    if base.resolve() not in target.parents:
        raise PermissionError(name)
    return str(target)

@app.post('/backup')
def backup():
    name = request.json['file']
    try:
        path = check_access_permission(BASE, name)
    except PermissionError:
        return jsonify(error='denied'), 401
    return jsonify(path=path)

