from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse
from pathlib import Path
app = FastAPI()
BASE = Path('/srv/agent')

def resolve_allowed(p: str) -> str:
    target = (BASE / p.lstrip('/')).resolve()
    if BASE.resolve() not in target.parents:
        raise ValueError('outside')
    return str(target)

@app.get('/image')
def image(path: str = ''):
    try:
        local = resolve_allowed(path)
    except ValueError:
        raise HTTPException(status_code=403)
    return FileResponse(local)

from flask import Flask, request, jsonify
from pathlib import Path
app = Flask(__name__)
ROOTS = [Path('/srv/music')]

def is_path_within_root_dirs(p: str) -> bool:
    resolved = Path(p).resolve()
    return any(resolved == r.resolve() or r.resolve() in resolved.parents for r in ROOTS)

@app.post('/dir-browser')
def list_folders():
    req_dir = request.json['folder']
    if not is_path_within_root_dirs(req_dir):
        return jsonify(error='denied'), 403
    path = Path(req_dir).resolve()
    return jsonify(dirs=[d.name for d in path.iterdir() if d.is_dir()])

from flask import Flask, request, redirect
from urllib.parse import urlsplit, urlunsplit
app = Flask(__name__)

def safe_next(target):
    if not target or '\\' in target:
        return '/'
    parsed = urlsplit(target)
    if (parsed.scheme and not parsed.netloc) or parsed.netloc.lower() not in ('', request.host.lower()):
        return '/'
    path = parsed.path or '/'
    if not path.startswith('/') or path.startswith('//'):
        return '/'
    return urlunsplit(('', '', path, parsed.query, parsed.fragment))

@app.post('/login')
def login():
    return redirect(safe_next(request.args.get('next')))

from flask import Flask, request
from urllib.parse import urlparse
app = Flask(__name__)

def safe_redirect(url, fallback='/settings'):
    if not url:
        return fallback
    p = urlparse(url)
    if p.scheme or p.netloc or not url.startswith('/') or url.startswith('//'):
        return fallback
    return url

@app.post('/save-settings')
def save_settings():
    resp = app.response_class('ok')
    resp.headers['Location'] = safe_redirect(request.form.get('past', ''))
    return resp

from flask import Flask, request, jsonify
from pathlib import Path
app = Flask(__name__)
BASE = Path('/srv/data')

def inside(p: Path) -> bool:
    try:
        p.resolve().relative_to(BASE.resolve())
        return True
    except ValueError:
        return False

def create_dir(name):
    target = BASE / name.strip('/')
    if not inside(target):
        return False
    target.mkdir(parents=True, exist_ok=True)
    return True

@app.post('/folders')
def create_folder():
    if not create_dir(request.json.get('path', '')):
        return jsonify(error='invalid'), 400
    return jsonify(ok=True)
